-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     REPORT_DATE,     ZERO_FREIGHT_SCENARIO,     CASE ZERO_FREIGHT_SCENARIO         WHEN 'NO_EXP_SETUP'         THEN 'No expense component configured for this order/location'         WHEN 'COMP_EXISTS_ZERO'         THEN 'Expense component exists but estimated expense value is zero'         WHEN 'EST_SET_ACTUAL_ZERO'         THEN 'Expense component set but zero value on received order'         ELSE 'Review required'     END                                                   AS ZERO_FREIGHT_DESC,     CASE         WHEN SHIPMENT_STATUS IN ('R','C')              AND ZERO_FREIGHT_SCENARIO IN ('NO_EXP_SETUP','COMP_EXISTS_ZERO')         THEN '1 - CRITICAL: Received order with zero freight - freight cost missing from stock ledger'         WHEN SHIPMENT_STATUS IN ('R','C')              AND ZERO_FREIGHT_SCENARIO = 'EST_SET_ACTUAL_ZERO'         THEN '2 - HIGH: Zero freight value on received order - WAC may be understated'         WHEN SHIPMENT_STATUS IN ('S','T')              AND ZERO_FREIGHT_SCENARIO = 'NO_EXP_SETUP'         THEN '3 - MEDIUM: In-transit order with no freight setup - resolve before receipt'         ELSE '4 - LOW: Monitor and verify'     END                                                   AS SEVERITY,     SHIPMENT_NO,     SHIPMENT_STATUS,     CASE SHIPMENT_STATUS         WHEN 'I' THEN 'Input'     WHEN 'S' THEN 'Shipped'         WHEN 'R' THEN 'Received'  WHEN 'C' THEN 'Closed'         ELSE SHIPMENT_STATUS     END                                                   AS SHIPMENT_STATUS_DESC,     ASN_NUMBER,     SHIP_DATE,     RECEIVE_DATE,     PO_NUMBER,     PO_STATUS,     CASE PO_STATUS         WHEN 'W' THEN 'Worksheet'   WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'    WHEN 'C' THEN 'Closed'         ELSE PO_STATUS     END                                                   AS PO_STATUS_DESC,     PO_WRITTEN_DATE,     SUPPLIER_ID,     SUPPLIER_NAME,     SUPPLIER_STATUS,     ORIGIN_COUNTRY_ID,     LOCATION_ID,     LOC_TYPE,     CASE LOC_TYPE         WHEN 'S' THEN STORE_NAME         WHEN 'W' THEN WH_NAME         ELSE TO_CHAR(LOCATION_ID)     END                                                   AS LOCATION_NAME,     DEPT_NO,     DEPT_NAME,     CLASS_NO,     CLASS_NAME,     SUBCLASS_NO,     SUBCLASS_NAME,     ITEM_ID,     ITEM_DESCRIPTION,     UOM,     CATCH_WEIGHT_IND,     QTY_ORDERED,     QTY_RECEIVED,     UNIT_COST,     ROUND(TOTAL_ORDERED_COST_RAW, 2)                     AS TOTAL_ORDERED_COST,     COMP_ID,     COMP_DESC,     COMP_RATE,     EST_EXP_VALUE,     COMP_CURRENCY,     ITEM_EXP_SEQ,     ITEM_EXP_ORIGIN_COUNTRY,     ITEM_EXP_RATE,     CASE         WHEN ITEM_EXP_RATE &gt; 0 AND UNIT_COST &gt; 0         THEN ROUND(TOTAL_ORDERED_COST_RAW * ITEM_EXP_RATE / 100, 2)     END                                                   AS EXPECTED_FREIGHT_PCT_VALUE,     CURRENT_SOH,     ROUND(CURRENT_SOH * NVL(WAC, 0), 2)                  AS SOH_COST_VALUE,     CASE         WHEN COMP_ID IS NULL         THEN 'MISSING: No ORDLOC_EXP record - expense profile not applied to this order/location'         WHEN NVL(COMP_RATE, 0) = 0 AND NVL(EST_EXP_VALUE, 0) = 0         THEN 'ZERO RATE: Expense component exists but COMP_RATE and EST_EXP_VALUE are both zero'         WHEN ITEM_EXP_SEQ IS NULL         THEN 'NO ITEM EXPENSE PROFILE: ITEM_EXP_HEAD missing for this item/supplier/country'         ELSE 'INVESTIGATE: Review batch_ordcostcompupd.ksh logs and ELC component setup'     END                                                   AS ROOT_CAUSE,     CASE         WHEN COMP_ID IS NULL AND ITEM_EXP_SEQ IS NULL         THEN 'Set up expense profile for item/supplier/country via Item Maintenance; re-run batch_ordcostcompupd.ksh'         WHEN COMP_ID IS NULL AND ITEM_EXP_SEQ IS NOT NULL         THEN 'Expense profile exists at item level but not applied to order - check batch_ordcostcompupd.ksh logs'         WHEN NVL(COMP_RATE, 0) = 0         THEN 'Update ELC component rate via batch_compeffupd.ksh; cascade to orders via batch_ordcostcompupd.ksh'         WHEN NVL(EST_EXP_VALUE, 0) = 0 AND SHIPMENT_STATUS IN ('R','C')         THEN 'Update ORDLOC_EXP for received order; post correcting cost adjustment if stock ledger impact required'         ELSE 'Review expense profile configuration and batch ELC update job schedule'     END                                                   AS RECOMMENDED_ACTION FROM (

