         NVL(ol.QTY_ORDERED,  0)                           AS QTY_ORDERED,         NVL(ol.QTY_RECEIVED, 0)                           AS QTY_RECEIVED,         NVL(ol.UNIT_COST,    0)                           AS UNIT_COST,         NVL(ol.QTY_ORDERED, 0) * NVL(ol.UNIT_COST, 0)    AS TOTAL_ORDERED_COST_RAW,         ole.COMP_ID                                       AS COMP_ID,         cd.CODE_DESC                                      AS COMP_DESC,         NVL(ole.COMP_RATE,     0)                         AS COMP_RATE,         NVL(ole.EST_EXP_VALUE, 0)                         AS EST_EXP_VALUE,         ole.COMP_CURRENCY                                 AS COMP_CURRENCY,         CASE             WHEN ole.COMP_ID IS NULL             THEN 'NO_EXP_SETUP'             WHEN NVL(ole.EST_EXP_VALUE, 0) = 0             THEN 'COMP_EXISTS_ZERO'             WHEN NVL(ole.EST_EXP_VALUE, 0) &gt; 0                  AND sh.STATUS_CODE IN ('R','C')             THEN 'EST_SET_ACTUAL_ZERO'             ELSE 'RECEIVED_NO_ACTUAL'         END                                               AS ZERO_FREIGHT_SCENARIO,         ieh.ITEM_EXP_SEQ                                  AS ITEM_EXP_SEQ,         ieh.ORIGIN_COUNTRY_ID                             AS ITEM_EXP_ORIGIN_COUNTRY,         NVL(ied.COMP_RATE, 0)                             AS ITEM_EXP_RATE,         NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH,         NVL(ils.AV_COST,       0)                         AS WAC     FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO    = oh.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDLOC               ol   ON  oh.ORDER_NO    = ol.ORDER_NO                                                     AND  sh.TO_LOC     = ol.LOCATION     LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  oh.ORDER_NO    = os.ORDER_NO                                                     AND  ol.ITEM       = os.ITEM     JOIN (

