<ds:display_name><ds:name>COMP_DESC</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(250)</ds:datatype><ds:sourceexpr>\"COMP_DESC\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>COMP_RATE</ds:name><ds:display_names><ds:display_name><ds:name>COMP_RATE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"COMP_RATE\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>EST_EXP_VALUE</ds:name><ds:display_names><ds:display_name><ds:name>EST_EXP_VALUE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"EST_EXP_VALUE\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>COMP_CURRENCY</ds:name><ds:display_names><ds:display_name><ds:name>COMP_CURRENCY</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(3)</ds:datatype><ds:sourceexpr>\"COMP_CURRENCY\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>ITEM_EXP_SEQ</ds:name><ds:display_names><ds:display_name><ds:name>ITEM_EXP_SEQ</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"ITEM_EXP_SEQ\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>ITEM_EXP_ORIGIN_COUNTRY</ds:name><ds:display_names><ds:display_name><ds:name>ITEM_EXP_ORIGIN_COUNTRY</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(3)</ds:datatype><ds:sourceexpr>\"ITEM_EXP_ORIGIN_COUNTRY\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>ITEM_EXP_RATE</ds:name><ds:display_names><ds:display_name><ds:name>ITEM_EXP_RATE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"ITEM_EXP_RATE\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>EXPECTED_FREIGHT_PCT_VALUE</ds:name><ds:display_names><ds:display_name><ds:name>EXPECTED_FREIGHT_PCT_VALUE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"EXPECTED_FREIGHT_PCT_VALUE\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>CURRENT_SOH</ds:name><ds:display_names><ds:display_name><ds:name>CURRENT_SOH</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"CURRENT_SOH\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>SOH_COST_VALUE</ds:name><ds:display_names><ds:display_name><ds:name>SOH_COST_VALUE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"SOH_COST_VALUE\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>ROOT_CAUSE</ds:name><ds:display_names><ds:display_name><ds:name>ROOT_CAUSE</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(82)</ds:datatype><ds:sourceexpr>\"ROOT_CAUSE\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>RECOMMENDED_ACTION</ds:name><ds:display_names><ds:display_name><ds:name>RECOMMENDED_ACTION</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>varchar(102)</ds:datatype><ds:sourceexpr>\"RECOMMENDED_ACTION\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column></ds:columns><ds:data-access-mode>auto</ds:data-access-mode></ds:table></ds:outputTables><ds:uiOptions>{\"version\":\"v5.2\",\"outputColumns\":[],\"transforms\":[],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 7 ────────────────────────────────────────────────────────────
SELECT\\n    REPORT_DATE,\\n    ZERO_FREIGHT_SCENARIO,\\n    CASE ZERO_FREIGHT_SCENARIO\\n        WHEN 'NO_EXP_SETUP'\\n        THEN 'No expense component configured for this order/location'\\n        WHEN 'COMP_EXISTS_ZERO'\\n        THEN 'Expense component exists but estimated expense value is zero'\\n        WHEN 'EST_SET_ACTUAL_ZERO'\\n        THEN 'Expense component set but zero value on received order'\\n        ELSE 'Review required'\\n    END                                                   AS ZERO_FREIGHT_DESC,\\n    CASE\\n        WHEN SHIPMENT_STATUS IN ('R','C')\\n             AND ZERO_FREIGHT_SCENARIO IN ('NO_EXP_SETUP','COMP_EXISTS_ZERO')\\n        THEN '1 - CRITICAL: Received order with zero freight - freight cost missing from stock ledger'\\n        WHEN SHIPMENT_STATUS IN ('R','C')\\n             AND ZERO_FREIGHT_SCENARIO = 'EST_SET_ACTUAL_ZERO'\\n        THEN '2 - HIGH: Zero freight value on received order - WAC may be understated'\\n        WHEN SHIPMENT_STATUS IN ('S','T')\\n             AND ZERO_FREIGHT_SCENARIO = 'NO_EXP_SETUP'\\n        THEN '3 - MEDIUM: In-transit order with no freight setup - resolve before receipt'\\n        ELSE '4 - LOW: Monitor and verify'\\n    END                                                   AS SEVERITY,\\n    SHIPMENT_NO,\\n    SHIPMENT_STATUS,\\n    CASE SHIPMENT_STATUS\\n        WHEN 'I' THEN 'Input'     WHEN 'S' THEN 'Shipped'\\n        WHEN 'R' THEN 'Received'  WHEN 'C' THEN 'Closed'\\n        ELSE SHIPMENT_STATUS\\n    END                                                   AS SHIPMENT_STATUS_DESC,\\n    ASN_NUMBER,\\n    SHIP_DATE,\\n    RECEIVE_DATE,\\n    PO_NUMBER,\\n    PO_STATUS,\\n    CASE PO_STATUS\\n        WHEN 'W' THEN 'Worksheet'   WHEN 'S' THEN 'Submitted'\\n        WHEN 'A' THEN 'Approved'    WHEN 'C' THEN 'Closed'\\n        ELSE PO_STATUS\\n    END                                                   AS PO_STATUS_DESC,\\n    PO_WRITTEN_DATE,\\n    SUPPLIER_ID,\\n    SUPPLIER_NAME,\\n    SUPPLIER_STATUS,\\n    ORIGIN_COUNTRY_ID,\\n    LOCATION_ID,\\n    LOC_TYPE,\\n    CASE LOC_TYPE\\n        WHEN 'S' THEN STORE_NAME\\n        WHEN 'W' THEN WH_NAME\\n        ELSE TO_CHAR(LOCATION_ID)\\n    END                                                   AS LOCATION_NAME,\\n    DEPT_NO,\\n    DEPT_NAME,\\n    CLASS_NO,\\n    CLASS_NAME,\\n    SUBCLASS_NO,\\n    SUBCLASS_NAME,\\n    ITEM_ID,\\n    ITEM_DESCRIPTION,\\n    UOM,\\n    CATCH_WEIGHT_IND,\\n    QTY_ORDERED,\\n    QTY_RECEIVED,\\n    UNIT_COST,\\n    ROUND(TOTAL_ORDERED_COST_RAW, 2)                     AS TOTAL_ORDERED_COST,\\n    COMP_ID,\\n    COMP_DESC,\\n    COMP_RATE,\\n    EST_EXP_VALUE,\\n    COMP_CURRENCY,\\n    ITEM_EXP_SEQ,\\n    ITEM_EXP_ORIGIN_COUNTRY,\\n    ITEM_EXP_RATE,\\n    CASE\\n        WHEN ITEM_EXP_RATE &gt; 0 AND UNIT_COST &gt; 0\\n        THEN ROUND(TOTAL_ORDERED_COST_RAW * ITEM_EXP_RATE / 100, 2)\\n    END                                                   AS EXPECTED_FREIGHT_PCT_VALUE,\\n    CURRENT_SOH,\\n    ROUND(CURRENT_SOH * NVL(WAC, 0), 2)                  AS SOH_COST_VALUE,\\n    CASE\\n        WHEN COMP_ID IS NULL\\n        THEN 'MISSING: No ORDLOC_EXP record - expense profile not applied to this order/location'\\n        WHEN NVL(COMP_RATE, 0) = 0 AND NVL(EST_EXP_VALUE, 0) = 0\\n        THEN 'ZERO RATE: Expense component exists but COMP_RATE and EST_EXP_VALUE are both zero'\\n        WHEN ITEM_EXP_SEQ IS NULL\\n        THEN 'NO ITEM EXPENSE PROFILE: ITEM_EXP_HEAD missing for this item/supplier/country'\\n        ELSE 'INVESTIGATE: Review batch_ordcostcompupd.ksh logs and ELC component setup'\\n    END                                                   AS ROOT_CAUSE,\\n    CASE\\n        WHEN COMP_ID IS NULL AND ITEM_EXP_SEQ IS NULL\\n        THEN 'Set up expense profile for item/supplier/country via Item Maintenance; re-run batch_ordcostcompupd.ksh'\\n        WHEN COMP_ID IS NULL AND ITEM_EXP_SEQ IS NOT NULL\\n        THEN 'Expense profile exists at item level but not applied to order - check batch_ordcostcompupd.ksh logs'\\n        WHEN NVL(COMP_RATE, 0) = 0\\n        THEN 'Update ELC component rate via batch_compeffupd.ksh; cascade to orders via batch_ordcostcompupd.ksh'\\n        WHEN NVL(EST_EXP_VALUE, 0) = 0 AND SHIPMENT_STATUS IN ('R','C')\\n        THEN 'Update ORDLOC_EXP for received order; post correcting cost adjustment if stock ledger impact required'\\n        ELSE 'Review expense profile configuration and batch ELC update job schedule'\\n    END                                                   AS RECOMMENDED_ACTION\\nFROM (\\n

-- ── Query 8 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        sh.SHIPMENT                                       AS SHIPMENT_NO,\\n        sh.STATUS_CODE                                    AS SHIPMENT_STATUS,\\n        sh.ASN                                            AS ASN_NUMBER,\\n        sh.SHIP_DATE                                      AS SHIP_DATE,\\n        sh.RECEIVE_DATE                                   AS RECEIVE_DATE,\\n        sh.ORDER_NO                                       AS PO_NUMBER,\\n        oh.STATUS                                         AS PO_STATUS,\\n        oh.WRITTEN_DATE                                   AS PO_WRITTEN_DATE,\\n        oh.SUPPLIER                                       AS SUPPLIER_ID,\\n        sp.SUP_NAME                                       AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                     AS SUPPLIER_STATUS,\\n        os.ORIGIN_COUNTRY_ID                              AS ORIGIN_COUNTRY_ID,\\n        sh.TO_LOC                                         AS LOCATION_ID,\\n        sh.TO_LOC_TYPE                                    AS LOC_TYPE,\\n        st.STORE_NAME                                     AS STORE_NAME,\\n        wh.WH_NAME                                        AS WH_NAME,\\n        im.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        im.CLASS                                          AS CLASS_NO,\\n        c.CLASS_NAME                                      AS CLASS_NAME,\\n        im.SUBCLASS                                       AS SUBCLASS_NO,\\n        sc.SUB_NAME                                       AS SUBCLASS_NAME,\\n        ol.ITEM                                           AS ITEM_ID,\\n        im.ITEM_DESC                                      AS ITEM_DESCRIPTION,\\n        im.STANDARD_UOM                                   AS UOM,\\n        im.CATCH_WEIGHT_IND                               AS CATCH_WEIGHT_IND,\\n        NVL(ol.QTY_ORDERED,  0)                           AS QTY_ORDERED,\\n        NVL(ol.QTY_RECEIVED, 0)                           AS QTY_RECEIVED,\\n        NVL(ol.UNIT_COST,    0)                           AS UNIT_COST,\\n        NVL(ol.QTY_ORDERED, 0) * NVL(ol.UNIT_COST, 0)    AS TOTAL_ORDERED_COST_RAW,\\n        ole.COMP_ID                                       AS COMP_ID,\\n        cd.CODE_DESC                                      AS COMP_DESC,\\n        NVL(ole.COMP_RATE,     0)                         AS COMP_RATE,\\n        NVL(ole.EST_EXP_VALUE, 0)                         AS EST_EXP_VALUE,\\n        ole.COMP_CURRENCY                                 AS COMP_CURRENCY,\\n        CASE\\n            WHEN ole.COMP_ID IS NULL\\n            THEN 'NO_EXP_SETUP'\\n            WHEN NVL(ole.EST_EXP_VALUE, 0) = 0\\n            THEN 'COMP_EXISTS_ZERO'\\n            WHEN NVL(ole.EST_EXP_VALUE, 0) &gt; 0\\n                 AND sh.STATUS_CODE IN ('R','C')\\n            THEN 'EST_SET_ACTUAL_ZERO'\\n            ELSE 'RECEIVED_NO_ACTUAL'\\n        END                                               AS ZERO_FREIGHT_SCENARIO,\\n        ieh.ITEM_EXP_SEQ                                  AS ITEM_EXP_SEQ,\\n        ieh.ORIGIN_COUNTRY_ID                             AS ITEM_EXP_ORIGIN_COUNTRY,\\n        NVL(ied.COMP_RATE, 0)                             AS ITEM_EXP_RATE,\\n        NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH,\\n        NVL(ils.AV_COST,       0)                         AS WAC\\n    FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh\\n    JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO    = oh.ORDER_NO\\n    JOIN  MFCS_RDS.RDS_WV_ORDLOC               ol   ON  oh.ORDER_NO    = ol.ORDER_NO\\n                                                    AND  sh.TO_LOC     = ol.LOCATION\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDSKU           os   ON  oh.ORDER_NO    = os.ORDER_NO\\n                                                    AND  ol.ITEM       = os.ITEM\\n    JOIN (\\n

-- ── Query 9 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS,\\n               STATUS, STANDARD_UOM, PACK_IND, CATCH_WEIGHT_IND\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                          im   ON  ol.ITEM        = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  im.DEPT        = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c    ON  im.DEPT        = c.DEPT\\n                                                    AND  im.CLASS      = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc   ON  im.DEPT        = sc.DEPT\\n                                                    AND  im.CLASS      = sc.CLASS\\n                                                    AND  im.SUBCLASS   = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp   ON  oh.SUPPLIER    = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st   ON  sh.TO_LOC      = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH               wh   ON  sh.TO_LOC      = wh.WH\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC_EXP       ole  ON  oh.ORDER_NO    = ole.ORDER_NO\\n                                                    AND  sh.TO_LOC     = ole.LOCATION\\n    LEFT JOIN (\\n

-- ── Query 10 ────────────────────────────────────────────────────────────
SELECT CODE, CODE_DESC\\n        FROM   MFCS_RDS.RDS_WV_CODE_DETAIL\\n        WHERE  CODE_TYPE = 'EXPC'\\n    )                                          cd   ON  ole.COMP_ID    = cd.CODE\\n    LEFT JOIN (\\n

-- ── Query 11 ────────────────────────────────────────────────────────────
SELECT ITEM, SUPPLIER, ORIGIN_COUNTRY_ID, ITEM_EXP_SEQ\\n        FROM   MFCS_RDS.RDS_WV_ITEM_EXP_HEAD\\n    )                                          ieh  ON  ol.ITEM        = ieh.ITEM\\n                                                    AND  oh.SUPPLIER   = ieh.SUPPLIER\\n                                                    AND  os.ORIGIN_COUNTRY_ID = ieh.ORIGIN_COUNTRY_ID\\n    LEFT JOIN (\\n

-- ── Query 12 ────────────────────────────────────────────────────────────
SELECT ITEM_EXP_SEQ, COMP_ID, COMP_RATE\\n        FROM   MFCS_RDS.RDS_WV_ITEM_EXP_DETAIL\\n    )                                          ied  ON  ieh.ITEM_EXP_SEQ = ied.ITEM_EXP_SEQ\\n                                                    AND  ole.COMP_ID   = ied.COMP_ID\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ol.ITEM        = ils.ITEM\\n                                                    AND  sh.TO_LOC     = ils.LOC\\n                                                    AND  sh.TO_LOC_TYPE = ils.LOC_TYPE\\n    WHERE\\n        sh.RECEIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n        AND (\\n            ole.COMP_ID IS NULL\\n            OR NVL(ole.EST_EXP_VALUE, 0) = 0\\n        )\\n)\"}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-03T15:54:59.773+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_205_Fresh_Freight_Zero_Balance'","parent-namespace":"ReCommon","parent-name":"RPT_205_Fresh_Freight_Zero_Balance","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_205_Fresh_Freight_Zero_Balance'"}
